  'This thread stays read-only. Retry the move, or cancel it. Cancel unlocks the thread only after {value0} confirms that it removed its copy. If {value1} already received the thread, cancel finishes the move instead.':
    'Ova nit ostaje samo za čitanje. Pokušajte ponovno premještanje ili ga otkažite. Odustani otključava nit tek nakon što {value0} potvrdi da je uklonio svoju kopiju. Ako je {value1} već primio nit, odustani završava premještanje.',
