  'This thread continues on {value0}. Open it there and send your next message. The copy here stays read-only for recovery.':
    'Ova nit se nastavlja na {value0}. Otvorite ga tamo i pošaljite sljedeću poruku. Kopija ovdje ostaje samo za čitanje radi oporavka.',
