  '{value0} symbolic links skipped.': '{value0} simboličke veze preskočene.',
  'Cancel move': 'Otkaži premještanje',
  'Cancel copy': 'Otkaži kopiju',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Premjestite cijeli spremljeni razgovor, kontrolni popis, privitke i datoteke. Sesije i vjerodajnice pružatelja usluga ostaju ovdje. Odredišna nit koristi zadani kabelski svežanj tog računala, s više pristupa nego što ova nit ima. Ništa se ne pokreće dok tamo ne pošaljete sljedeću poruku. Možete promijeniti njegov model nakon što se otvori. Ova nit ostaje ovdje, samo za čitanje, radi oporavka.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Kopirajte datoteke i lokalnu Git povijest. Izvorni projekt i razgovori ostaju ovdje. Na odredištu se stvara nova mapa. Radna stabla koriste svoj konfigurirani direktorij radnog stabla.',
