  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Postavite CuaDriver na ovom hostu za vrijeme izvođenja. CuaDriver posjeduje OS dozvole; Dovo povezuje agente preko MCP-a.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Imena ili staze izvršnih datoteka hosta, bez navođenja ljuske. Zaobilaženja agenta imaju prednost. Novi terminali koriste ove postavke ljuske.',
