  'Relay fallback': 'Zamjena releja',
  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'Računalo mora dopustiti relej u QR-u za uparivanje. Za uparivanje samo izravno, generirajte novi QR s omogućenim Dovo-om na računalu i ponovno uparite.',
  'Scan pairing QR code': 'Skenirajte QR kod za uparivanje',
  'Point your camera at the QR code shown by Dovo Studio or the server’s pair command.':
    'Usmjerite svoju kameru prema QR kodu koji prikazuje Dovo Studio ili poslužiteljskoj naredbi za uparivanje.',
  'Allow camera access to scan a pairing code. You can also enter the address and code manually.':
    'Dopustite pristup kameri za skeniranje koda za uparivanje. Adresu i šifru možete unijeti i ručno.',
  'Allow camera': 'Dopusti kameru',
  'Open Settings': 'Otvorite postavke',
  'Try another code': 'Pokušajte s drugim kodom',
  'Enter address and code manually': 'Unesite adresu i kod ručno',
  'Enter the new address and a fresh pairing code from the same computer. Your saved connection stays unchanged until pairing succeeds.':
    'Unesite novu adresu i novi kod za uparivanje s istog računala. Vaša spremljena veza ostaje nepromijenjena dok uparivanje ne uspije.',
  'On your computer, open Dovo and choose {value0} in Settings → Devices & runtime.':
    'Na računalu otvorite Dovo i odaberite {value0} u Postavke → Uređaji i okruženje za izvođenje.',
  'Connect your phone': 'Povežite svoj telefon',
