    'Pokreće agenta svakog novog razgovora, njegove naredbe i terminale u lokalnom Docker ili Podman spremniku. Montiraju se samo radna kopija i prijava odabranog agenta. Razgovori u tijeku zadržavaju svoju postavku.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Bez pristupa mreži agent ne može doći do API-ja svog modela, osim ako taj API radi unutar pješčanika. Instalacije paketa i web-zahtjevi također ne uspijevaju.',
