  'The agent runs on this computer with your user account.':
    'Agent radi na ovom računalu s vašim korisničkim računom.',
  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'Agent, njegove naredbe i terminali rade u spremniku. Montiraju se samo ova radna kopija i prijava agenta.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Zadržava novi rad koji se izvodi bez vaše poruke kada njegov procijenjeni trošak dosegne ograničenje. To uključuje nastavke Botova, korake rutina Bota, zakazane poruke i podređene agente. Svaka nit ili Bot broji se zajedno sa svojim podređenim agentima. Rutina bez Bota započinje novo brojanje pri svakom pokretanju. Njezina vlastita ograničenja postavite u odjeljku Praćenje i ograničenja. Vaša sljedeća poruka ili Nastavi poništava brojanje. Krugovi bez cijene također zadržavaju rad. Krug koji je u tijeku uvijek završava.',
  'During your request: "{value0}"': 'Tijekom tvog zahtjeva: "{value0}"',
